  P.shopPrice=function(item){const stage=this.stageNumber(),disc=Math.min(.32,this.perkRank('bargain')*.08);return Math.max(20,Math.round(item.price*(1+(stage-1)*.035)*(1-disc)));};
  P.buyShop=function(id){const item=SHOP_ITEMS[id];if(!item)return;const price=this.shopPrice(item);if(this.state.credits<price){this.toast('Not enough multiverse credits.');return;}if(id==='reroll_service'&&this.state.pending){this.toast('Wheel recalibration is only available between events.');return;}this.state.credits-=price;if(item.kind==='consumable')this.state.consumables[id]=(this.state.consumables[id]||0)+1;else if(id==='artifact_crate')(this.acquireArtifactV5?this.acquireArtifactV5(this.pick(DATA.artifacts).id,true):this.acquireArtifact(this.pick(DATA.artifacts).id,true));else if(id==='form_cache'){const pool=DATA.transformations.filter(f=>!f.secret&&!this.state.forms.includes(f.id));if(pool.length)this.acquireForm(this.pick(pool).id,true);}else if(id==='power_cache'){const pool=DATA.characters.filter(c=>!this.state.kits.some(k=>k.id===c.id));if(pool.length)this.acquireKit(this.pick(pool).id,true);}else if(id==='full_service'){this.state.statuses=[];this.syncVitals(true);}else if(id==='reroll_service')this.generateWheel();this.log(`SHOP: Purchased ${item.name} for ${price} credits.`,'info');this.save();this.renderAll();this.renderShopMenu();};
  P.useConsumable=function(id){const n=this.state.consumables[id]||0;if(n<=0){this.toast('None in inventory.');return;}const item=SHOP_ITEMS[id];if(!item)return;if(id==='revive_chip'){this.toast('Continuity Anchors trigger automatically on knockout.');return;}this.state.consumables[id]=n-1;if(id==='med_gel')this.heal(Math.round(this.maxHP()*.45));else if(id==='energy_cell')this.restoreEnergy(Math.round(this.maxEnergyPool()*.50));else if(id==='full_restore'){this.syncVitals(true);const neg=this.state.statuses.findIndex(s=>!STATUS_EFFECTS[s.id]?.good);if(neg>=0)this.state.statuses.splice(neg,1);}else if(id==='mastery_token'){if(this.state.kits.length){const k=this.pick(this.state.kits);k.mastery=Math.min(5,(k.mastery||1)+1);this.log(`TRAINING PASS: ${CHAR.get(k.id).name} mastery is now ${k.mastery}.`,'rare');}else{this.state.consumables[id]++;this.toast('Acquire a power set first.');return;}}else if(id==='form_battery')this.state.formFreeCharge++;else if(id==='shield_charge')this.state.tempShield+=90;this.log(`USED: ${item.name}.`,'info');this.save();this.renderAll();this.renderShopMenu();};
