  P.fuseAbilities=function(aKey,bKey){if(!aKey||!bKey||aKey===bKey){this.toast('Choose two different equipped abilities.');return;}if(this.state.fusedAbilities.length>=3){this.toast('Fusion Lab capacity is 3 techniques. Delete one first.');return;}const all=this.techniqueCatalog(),a=all.find(t=>this.techKey(t)===aKey),b=all.find(t=>this.techKey(t)===bKey);if(!a||!b)return;const id=`fusion:${h32(aKey+'|'+bKey+'|'+Date.now())}`,name=`${a.name.split(/[:—-]/)[0].trim()} × ${b.name.split(/[:—-]/)[0].trim()}`,tags=[...new Set([...(a.tags||[]),...(b.tags||[])])],cost=Math.round((a.cost+b.cost)*.72+8);this.state.fusedAbilities.push({id,key:id,name,source:'Fusion Lab',tags,mastery:5,cost,damageBonus:.20});if(this.state.abilityLoadout.length<this.maxAbilitySlots())this.state.abilityLoadout.push(id);this.log(`POWER FUSION CREATED: ${name}.`,'rare');this.save();this.renderAbilitiesMenu();};
