  const _applyRecoveryV6=P.applyRecovery;P.applyRecovery=function(id,mode='heal',quiet=false){const r=_applyRecoveryV6.call(this,id,mode,quiet);this.syncVitals();if(mode==='heal')this.syncVitals(true);else{this.heal(Math.round(this.maxHP()*.30));this.restoreEnergy(Math.round(this.maxEnergyPool()*.55));}return r;};
