  P.generateOriginStory=function(forceRandom=true){const pick=(arr,id)=>{const el=document.getElementById(id);if(!forceRandom&&el?.value)return el.value;return arr[Math.floor(Math.random()*arr.length)];},bg=pick(ORIGIN_BACKGROUNDS,'v6-origin-background'),cat=pick(ORIGIN_CATALYSTS,'v6-origin-catalyst'),comp=pick(ORIGIN_COMPLICATIONS,'v6-origin-complication'),mot=pick(ORIGIN_MOTIVATIONS,'v6-origin-motivation'),tone=pick(ORIGIN_TONES,'v6-origin-tone'),code=(document.getElementById('v6-cc-codename')?.value||this.state.customCharacter.codename||'Riftwalker').trim(),name=(document.getElementById('v6-cc-name')?.value||this.state.customCharacter.name||'Alex').trim(),story=`${name}, later known as ${code}, was ${bg}. Everything changed when ${cat}. The event did not grant a permanent borrowed identity; instead it created a channel that could learn power signatures from heroes and villains encountered across realities. The price was immediate: ${comp}. Now ${code} travels from world to world to ${mot}. The story plays as a ${tone} saga, and every copied ability forces a new question: how much power can one person carry without letting the people it came from define who they become?`;const ta=document.getElementById('v6-origin-story');if(ta)ta.value=story;return story;};
