  P.renderHub=(function(old){return function(){old.call(this);const cc=this.state.customCharacter,btn=document.getElementById('spin-btn'),e=this.effectiveStats();document.getElementById('hub-kicker').textContent=this.state.characterReady?'CUSTOM MULTIVERSE CHARACTER':'CREATE YOUR CHARACTER';document.getElementById('hub-name').textContent=this.state.characterReady?(cc.codename||cc.name):'CHARACTER SETUP REQUIRED';document.getElementById('hub-meta').textContent=this.state.characterReady?`${cc.name} • ${V6_ARCHETYPES[cc.archetype]?.name||'Adaptive'}`:`${ORIGIN_COMBINATIONS.toLocaleString()}+ origin-story combinations`;document.getElementById('hub-overall').textContent=this.state.characterReady?`OVR ${Math.round(this.overall(e))} • ${this.abilityCount()} ABILITIES`:'BUILD • ORIGIN • CAMPAIGN';if(!this.state.characterReady){btn.disabled=false;btn.textContent='CREATE CHARACTER';}else if(!this.state.pending&&!this.state.ended){const next=this.state.spin+1;btn.textContent=next===1?'SPIN FIRST POWER':next%10===0?`SPIN STAGE ${next/10} BOSS`:'SPIN MULTIVERSE';}};})(P.renderHub);
