  P.decorateEventMedia=function(){const p=this.state.pending;if(!p||['battle','boss','activity','ending'].includes(p.type))return;let src='',label='';if(['power','recruit'].includes(p.type)){const c=CHAR.get(p.ref);src=this.characterPortrait(c);label=c?.name||p.label;}else if(p.type==='transform'){const f=FORM.get(p.ref);src=this.formPortrait(f,`global:${p.ref}`);label=f?.name||p.label;}else if(p.type==='artifact'){src=artSVG(p.label,'ARTIFACT','artifact|'+p.ref,'#ffd54a','peak',['tech']);label=p.label;}else if(p.type==='hazard'){src=artSVG(p.label,p.sub||'HAZARD','hazard|'+p.ref,'#f97316','peak',['energy']);label=p.label;}if(src&&!this.eventPanel.querySelector('.v6-event-art'))this.eventPanel.insertAdjacentHTML('afterbegin',`<div class="v6-event-art"><img src="${src}" alt="${esc(label)} art"></div>`);};
