  P.renderActivity=function(p){const a=ACTIVITIES[p.ref];if(!a)return;if(p.stage==='result'){this.eventPanel.innerHTML=this.eventHeader('activity',a.name,p.resultText||'Activity complete.')+`<div class="v6-event-art"><img src="${artSVG(a.name,a.category,'activity|'+p.ref,'#14b8a6','peak',a.tags)}" alt=""></div><div class="resolve-row"><button class="primary-btn" data-action="continue">CONTINUE</button></div>`;return;}const enemy=CHAR.get(p.opponentId),techs=this.combatTechniques(enemy).slice(0,this.maxAbilitySlots()+2);if(!p.technique&&techs[0])p.technique=techs[0].id;const safe=this.activityOdds(p,'safe'),std=this.activityOdds(p,'standard'),risk=this.activityOdds(p,'risk');this.eventPanel.innerHTML=this.eventHeader('activity',a.name,`${a.category} • ${a.desc}`)+(enemy?`<div class="v6-activity-rival"><img src="${this.characterPortrait(enemy)}" alt=""><div><b>RIVAL: ${esc(enemy.name)}</b><small>${esc(enemy.universe)} • OVR ${Math.round(this.overall(enemy.stats))}</small></div></div>`:'')+`<div class="v6-event-art"><img src="${artSVG(a.name,a.category,'activity|'+p.ref,'#14b8a6','peak',a.tags)}" alt=""></div><div class="v6-tech-grid">${techs.map(t=>`<button class="v5-tech ${p.technique===t.id?'selected':''}" data-action="technique" data-value="${t.id}"><b>${esc(t.name)}</b><small>${t.cost||0} EN • ${esc(t.source)}</small></button>`).join('')}</div><div class="choice-grid three"><button class="choice-btn good" data-action="v6-activity" data-value="safe"><strong>SAFE RUN — ${Math.round(safe.odds*100)}%</strong><small>Lower energy and reward.</small></button><button class="choice-btn" data-action="v6-activity" data-value="standard"><strong>STANDARD — ${Math.round(std.odds*100)}%</strong><small>Balanced risk and prize.</small></button><button class="choice-btn gold" data-action="v6-activity" data-value="risk"><strong>ALL-OUT — ${Math.round(risk.odds*100)}%</strong><small>Harder, more expensive, larger prize.</small></button></div>`;};
