  P.renderAbilitiesMenu=function(){const body=document.getElementById('v6-abilities-body');if(!body)return;const all=this.techniqueCatalog(),load=new Set(this.state.abilityLoadout),max=this.maxAbilitySlots(),cards=all.map(t=>{const key=this.techKey(t),on=load.has(key),disabled=!on&&load.size>=max;return`<div class="v6-menu-card"><div><b>${esc(t.name)}</b><small>${esc(t.source)} • ${t.cost||0} EN • ${(t.tags||[]).slice(0,5).map(titleCase).join(', ')}</small></div><button data-v6-ability="${on?'unequip':'equip'}" data-key="${esc(key)}" ${disabled?'disabled':''}>${on?'UNEQUIP':'EQUIP'}</button></div>`;}).join(''),equipped=[...load].map(k=>all.find(t=>this.techKey(t)===k)).filter(Boolean);body.innerHTML=`<div class="v6-menu-intro"><b>ABILITY LOADOUT — ${load.size}/${max}</b><span>Only equipped techniques appear in combat unless the loadout is empty. Mastery still controls which copied powers are available.</span></div><div class="v6-inline-actions"><button id="v6-auto-loadout">AUTO-EQUIP BEST</button><button id="v6-clear-loadout">CLEAR</button></div><h3>Power Fusion Lab</h3><div class="v6-fusion-row"><select id="v6-fuse-a">${equipped.map(t=>`<option value="${esc(this.techKey(t))}">${esc(t.name)}</option>`).join('')}</select><select id="v6-fuse-b">${equipped.map(t=>`<option value="${esc(this.techKey(t))}">${esc(t.name)}</option>`).join('')}</select><button id="v6-fuse-btn">FUSE</button></div><div class="v6-fusions">${(this.state.fusedAbilities||[]).map(f=>`<span>${esc(f.name)} • ${f.cost} EN <button data-v6-fusion-delete="${f.id}">×</button></span>`).join('')||'<small>No custom fusion techniques yet.</small>'}</div><h3>Available Techniques</h3><div class="v6-menu-list">${cards||'<div class="event-empty">Acquire a character power set to unlock superhuman abilities.</div>'}</div>`;};
